fn insert_sorted(acc: Vec<Int>, x: Int) -> Vec<Int> {
    let out = vec()
    let placed = false
    for y in acc {
        if placed {
            out = push(out, y)
        } else {
            if y < x {
                out = push(out, y)
            } else {
                out = push(out, x)
                out = push(out, y)
                placed = true
            }
        }
    }
    if placed {
        out
    } else {
        push(out, x)
    }
}

