fn get_or_empty(v: &Vec<Str>, i: Int) -> Str {
    match get(&v, i) {
        Some(x) => x,
        None => ""
    }
}

fn is_pal(s: &Str) -> Bool {
    let cs = chars(&s)
    let n = len(&cs)
    let ok = true
    let i = 0
    while i < n {
        let a = get_or_empty(&cs, i)
        let b = get_or_empty(&cs, n - 1 - i)
        let same = &a == &b
        drop a
        drop b
        if same == false {
            ok = false
        }
        i = i + 1
    }
    drop cs
    ok
}

